package vn.iotstar.service.impl;import org.springframework.data.domain.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.iotstar.dto.UserDTO;import vn.iotstar.entity.*;import vn.iotstar.mapper.UserMapper;import vn.iotstar.repository.*;import vn.iotstar.service.UserService;@Service public class UserServiceImpl implements UserService{public UserServiceImpl(UserRepository ur,RoleRepository rr,UserMapper mapper,PasswordEncoder enc){this.ur=ur;this.rr=rr;this.mapper=mapper;this.enc=enc;}final UserRepository ur;final RoleRepository rr;final UserMapper mapper;final PasswordEncoder enc;@Transactional(readOnly=true)public Page<UserDTO> findAll(String k,int p,int s){Pageable x=PageRequest.of(Math.max(0,p),Math.max(1,s),Sort.by(Sort.Direction.DESC,"id"));return ur.search(k==null?"":k,x).map(u->{UserDTO d=mapper.toDTO(u);d.setProductCount(ur.countProductsByUserId(u.getId()));return d;});}@Transactional(readOnly=true)public UserDTO findById(Long id){User u=ur.findById(id).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));UserDTO d=mapper.toDTO(u);d.setProductCount(ur.countProductsByUserId(id));return d;}@Transactional public UserDTO create(UserDTO d){if(ur.existsByUsername(d.getUsername()))throw new IllegalArgumentException("Username đã tồn tại");if(ur.existsByEmail(d.getEmail()))throw new IllegalArgumentException("Email đã tồn tại");User u=mapper.toEntity(d);Role r=rr.findByName(d.getRoleName()==null||d.getRoleName().isBlank()?"ROLE_USER":d.getRoleName()).orElseThrow(()->new IllegalArgumentException("Role không tồn tại"));u.setRole(r);u.setPassword(enc.encode("123456"));u.setEnabled(d.isEnabled());return mapper.toDTO(ur.save(u));}@Transactional public UserDTO update(Long id,UserDTO d){User u=ur.findById(id).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));if(!u.getUsername().equals(d.getUsername())&&ur.existsByUsername(d.getUsername()))throw new IllegalArgumentException("Username đã tồn tại");if(!u.getEmail().equals(d.getEmail())&&ur.existsByEmail(d.getEmail()))throw new IllegalArgumentException("Email đã tồn tại");u.setUsername(d.getUsername());u.setEmail(d.getEmail());u.setFullName(d.getFullName());u.setEnabled(d.isEnabled());if(d.getRoleName()!=null&&!d.getRoleName().isBlank())u.setRole(rr.findByName(d.getRoleName()).orElseThrow(()->new IllegalArgumentException("Role không tồn tại")));return mapper.toDTO(ur.save(u));}@Transactional public void delete(Long id){User u=ur.findById(id).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));if(!u.getProducts().isEmpty())throw new IllegalArgumentException("User đang có Product, hãy xóa Product trước.");ur.delete(u);}@Transactional(readOnly=true)public long countUsers(){return ur.count();}@Transactional(readOnly=true)public long countProducts(Long id){return ur.countProductsByUserId(id);}}
